import { formatPythonInt } from '../numbers/pythonInt.mjs';

function escapePythonBytesCharacter(character) {
  if (character === '\\') {
    return '\\\\';
  }

  if (character === '\'') {
    return '\\\'';
  }

  const code = character.charCodeAt(0);

  if (code >= 32 && code <= 126) {
    return character;
  }

  return `\\x${code.toString(16).padStart(2, '0')}`;
}

export function formatPythonBytesLiteral(value) {
  return `b'${Array.from(value, (character) => escapePythonBytesCharacter(character)).join('')}'`;
}

export function formatPythonValue(value) {
  if (typeof value === 'bigint') {
    return formatPythonInt(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonValue(item)).join(', ')}]`;
  }

  throw new TypeError('Unsupported Python display value');
}

