import { decodeBencode, encodeBencode } from './bencode/index.mjs';
import {
  HELP_TEXT,
  PROGRAM_NAME,
  USAGE_LINE,
  parseReferenceArgs,
} from './cli/referenceCli.mjs';
import { formatPythonBytesLiteral, formatPythonValue } from './format/pythonDisplay.mjs';

function defaultIo() {
  return {
    writeStdout(text) {
      process.stdout.write(text);
    },
    writeStderr(text) {
      process.stderr.write(text);
    },
  };
}

function writeError(io, message) {
  io.writeStderr(`${USAGE_LINE}\n${PROGRAM_NAME}: error: ${message}\n`);
}

export function runTest14(argv, io = defaultIo()) {
  const parsed = parseReferenceArgs(argv);

  if (parsed.kind === 'help') {
    io.writeStdout(HELP_TEXT);
    return 0;
  }

  if (parsed.kind === 'error') {
    writeError(io, parsed.message);
    return 2;
  }

  const { a, b } = parsed.values;
  const numbers = [a, b, a + b, a * b];
  const encoded = encodeBencode(numbers);
  const decoded = decodeBencode(encoded);
  const encodedNegative = encodeBencode(-a);
  const encodedZero = encodeBencode(0n);

  io.writeStdout(`${formatPythonBytesLiteral(encoded)}\n`);
  io.writeStdout(`${formatPythonValue(decoded)}\n`);
  io.writeStdout(`${formatPythonBytesLiteral(encodedNegative)}\n`);
  io.writeStdout(`${formatPythonBytesLiteral(encodedZero)}\n`);
  return 0;
}

